create table public.lms_courses (id uuid primary key default gen_random_uuid(), title text not null, description text not null default '', status text not null default 'draft' check(status in ('draft','published','archived')), created_at timestamptz not null default now());
create table public.lms_lessons (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.lms_courses(id) on delete restrict, title text not null, content text not null default '', order_no int not null, unique(course_id,order_no));
create table public.lms_enrollments (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.lms_courses(id) on delete restrict, student_id uuid not null references public.profiles(id) on delete restrict, status text not null default 'active' check(status in ('active','completed','withdrawn')), enrolled_at timestamptz not null default now(), unique(course_id,student_id));
create table public.lms_progress (id uuid primary key default gen_random_uuid(), enrollment_id uuid not null references public.lms_enrollments(id) on delete cascade, lesson_id uuid not null references public.lms_lessons(id) on delete restrict, student_id uuid not null references public.profiles(id) on delete restrict, completed_at timestamptz not null default now(), unique(enrollment_id,lesson_id));
revoke all on public.lms_courses,public.lms_lessons,public.lms_enrollments,public.lms_progress from anon,authenticated;
grant select on public.lms_courses,public.lms_lessons,public.lms_enrollments,public.lms_progress to authenticated;
alter table public.lms_courses enable row level security; alter table public.lms_lessons enable row level security; alter table public.lms_enrollments enable row level security; alter table public.lms_progress enable row level security;
create policy lms_course_read on public.lms_courses for select to authenticated using(lms_courses.status='published' and exists(select 1 from public.lms_enrollments e where e.course_id=lms_courses.id and e.student_id=(select auth.uid()) and e.status='active'));
create policy lms_lesson_read on public.lms_lessons for select to authenticated using(exists(select 1 from public.lms_enrollments e join public.lms_courses c on c.id=lms_lessons.course_id where e.course_id=lms_lessons.course_id and e.student_id=(select auth.uid()) and e.status='active' and c.status='published'));
create policy lms_enrollment_read on public.lms_enrollments for select to authenticated using(student_id=(select auth.uid()));
create policy lms_progress_read on public.lms_progress for select to authenticated using(student_id=(select auth.uid()));
create or replace function public.mark_lesson_progress(p_lesson_id uuid,p_student_id uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare progress_id uuid; begin if p_student_id<>(select auth.uid()) then raise exception 'actor mismatch'; end if; insert into public.lms_progress(enrollment_id,lesson_id,student_id) select e.id,p_lesson_id,p_student_id from public.lms_enrollments e join public.lms_lessons l on l.course_id=e.course_id join public.lms_courses c on c.id=e.course_id where e.student_id=p_student_id and e.status='active' and l.id=p_lesson_id and c.status='published' on conflict(enrollment_id,lesson_id) do update set completed_at=now() returning id into progress_id; if progress_id is null then raise exception 'lesson not available'; end if; return progress_id; end $$;
revoke all on function public.mark_lesson_progress(uuid,uuid) from public; grant execute on function public.mark_lesson_progress(uuid,uuid) to authenticated;
